import {esc,short} from './core.js';
import {bundleWalletRows} from './bundle-reports.js';
export function walletMap(report,selected=''){
 const all=bundleWalletRows(report),rows=all.slice(0,8),n=rows.length;
 if(!n)return '<div class="map-empty">No grouped recipient wallets to map in this sample.</div>';
 const nodes=rows.map((row,i)=>{const angle=-Math.PI/2+i*2*Math.PI/n;return {...row,x:260+Math.cos(angle)*185,y:150+Math.sin(angle)*104};});
 return `<div class="wallet-map"><svg viewBox="0 0 520 300" role="img" aria-label="Observed same-slot recipient associations. Links show shared slot membership, not transfers or ownership."><circle class="map-orbit" cx="260" cy="150" r="101"/>${nodes.map(r=>`<line class="map-edge ${selected===r.owner?'selected':''}" x1="260" y1="150" x2="${r.x.toFixed(2)}" y2="${r.y.toFixed(2)}"/>`).join('')}<rect class="map-center" x="210" y="128" width="100" height="44" rx="10"/><text class="map-center-label" x="260" y="147" text-anchor="middle">${report.groups.length} SLOT GROUP${report.groups.length===1?'':'S'}</text><text class="map-center-sub" x="260" y="162" text-anchor="middle">OBSERVED SAMPLE</text>${nodes.map(r=>`<a href="#wallet-evidence" data-action="filter-bundle-owner" data-owner="${esc(r.owner)}" aria-label="Filter evidence for ${esc(r.owner)}"><title>${esc(r.owner)} · ${r.transactionCount} acquisition transaction(s)</title><rect class="map-node ${selected===r.owner?'selected':''}" x="${(r.x-48).toFixed(2)}" y="${(r.y-17).toFixed(2)}" width="96" height="34" rx="7"/><text class="map-node-label" x="${r.x.toFixed(2)}" y="${(r.y+3).toFixed(2)}" text-anchor="middle">${esc(short(r.owner,4))}</text></a>`).join('')}</svg><p>Click a wallet to filter its proof. Lines show slot associations, not token transfers or common ownership.${all.length>8?' Showing 8 of '+all.length+' wallets; all appear in the evidence table.':''}</p></div>`;
}
